#!/bin/bash
# Створює ярлик "Cyber Launcher" на робочому столі.
# Запускати з папки лаунчера: bash make_shortcut.sh
set -e
PROJECT="$(cd "$(dirname "$0")" && pwd)"
APP="$HOME/Desktop/Cyber Launcher.app"

if [ ! -x "$PROJECT/build/launcher" ]; then
  echo "Не знайдено build/launcher. Спершу збери лаунчер: cmake -B build && cmake --build build"
  exit 1
fi

rm -rf "$APP"
mkdir -p "$APP/Contents/MacOS" "$APP/Contents/Resources"

cat > "$APP/Contents/MacOS/CyberLauncher" << EOF
#!/bin/bash
cd "$PROJECT"
exec ./build/launcher >> launcher.log 2>&1
EOF
chmod +x "$APP/Contents/MacOS/CyberLauncher"

cat > "$APP/Contents/Info.plist" << 'EOF'
<?xml version="1.0" encoding="UTF-8"?>
<!DOCTYPE plist PUBLIC "-//Apple//DTD PLIST 1.0//EN" "http://www.apple.com/DTDs/PropertyList-1.0.dtd">
<plist version="1.0">
<dict>
  <key>CFBundleExecutable</key><string>CyberLauncher</string>
  <key>CFBundleIdentifier</key><string>local.cyberlauncher</string>
  <key>CFBundleName</key><string>Cyber Launcher</string>
  <key>CFBundleDisplayName</key><string>Cyber Launcher</string>
  <key>CFBundleIconFile</key><string>icon</string>
  <key>CFBundlePackageType</key><string>APPL</string>
  <key>CFBundleVersion</key><string>1.0</string>
  <key>NSHighResolutionCapable</key><true/>
</dict>
</plist>
EOF

base64 --decode > "$APP/Contents/Resources/icon.icns" << 'ICON'
